import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Introducing Ceph Mgmt-gateway- Unified Access, OIDC-based SSO, and HA for Manageme... R. K. Elhichou","description":"","frontmatter":{"title":"Introducing Ceph Mgmt-gateway- Unified Access, OIDC-based SSO, and HA for Manageme... R. K. Elhichou","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-19T00:00:00.000Z","tags":["Ceph Management Gateway","OIDC-based SSO","High Availability","Ceph Monitoring and Management","Ceph Security"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Introducing_Ceph_Mgmt-gateway_-_Unified_Access_OIDC-based_SSO_and_HA_for_Manageme..._R._K._Elhichou.md","filePath":"posts/2025/Introducing_Ceph_Mgmt-gateway_-_Unified_Access_OIDC-based_SSO_and_HA_for_Manageme..._R._K._Elhichou.md","lastUpdated":1780459816000}'),n={name:"posts/2025/Introducing_Ceph_Mgmt-gateway_-_Unified_Access_OIDC-based_SSO_and_HA_for_Manageme..._R._K._Elhichou.md"};function i(l,e,s,g,d,_){return t(),o("div",null,[...e[0]||(e[0]=[r('<h3 id="ceph-管理网关功能介绍会议纪要" tabindex="-1">Ceph 管理网关功能介绍会议纪要 <a class="header-anchor" href="#ceph-管理网关功能介绍会议纪要" aria-label="Permalink to &quot;Ceph 管理网关功能介绍会议纪要&quot;">​</a></h3><h4 id="会议基本信息" tabindex="-1"><strong>会议基本信息</strong> <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;**会议基本信息**&quot;">​</a></h4><ul><li><strong>主题</strong>: 介绍 Ceph 新功能“安全管理网关”</li><li><strong>主讲人</strong>: Redwan（IBM 软件架构师，Ceph 编排团队核心贡献者）</li><li><strong>会议目标</strong>: 讲解 Ceph 下一个版本（Tentacle）中的安全管理网关功能，旨在简化管理和监控系统架构，提高安全性和可用性。</li></ul><h4 id="关键讨论内容" tabindex="-1"><strong>关键讨论内容</strong> <a class="header-anchor" href="#关键讨论内容" aria-label="Permalink to &quot;**关键讨论内容**&quot;">​</a></h4><ol><li><p><strong>现有架构痛点</strong></p><ul><li>Ceph 监控和管理服务（如 Prometheus、Grafana、Dashboard 等）分散，访问复杂，用户体验割裂。</li><li>认证机制不统一，各服务独立认证，缺乏统一身份管理。</li><li>高可用性不足，监控栈（如 Prometheus）无原生 HA 支持，存在单点故障风险。</li><li>安全性缺陷，TLS 配置分散，内部服务通信未强制 mTLS，存在安全风险。</li></ul></li><li><p><strong>新架构设计</strong></p><ul><li><strong>Management Gateway</strong>: 统一入口，提供 HTTPS 终结点和负载均衡，简化访问。</li><li><strong>OAuth2 Proxy</strong>: 集成外部身份提供商（IDP），支持 SSO（如 Keycloak、Red Hat SSO、Azure AD），提供统一认证。</li><li><strong>内部 CA</strong>: 基于 <code>cephadm</code> 签发证书，强制服务间 mTLS 认证，提高安全性。</li><li><strong>高可用性实现</strong>: 多实例部署 + Keepalived（VRRP 协议）提供虚拟 IP（VIP）故障转移，后端服务多活冗余。</li></ul></li><li><p><strong>功能优势</strong></p><ul><li><strong>统一访问</strong>: 单端点访问所有服务，如 <code>/grafana</code>、<code>/prometheus</code>。</li><li><strong>企业级 SSO</strong>: 支持 OIDC 协议，兼容主流 IDP。</li><li><strong>安全性提升</strong>: 前端 TLS 终止 + 后端 mTLS 加密，集中式证书生命周期管理。</li><li><strong>运维简化</strong>: 通过 <code>cephadm</code> 自动化配置。</li></ul></li><li><p><strong>Demo 演示</strong></p><ul><li>SSO 登录演示，用户通过 VIP 访问 Dashboard，重定向至 Keycloak 完成认证后无缝访问所有服务。</li><li>故障恢复测试，展示 Manager 切换、Grafana 实例故障转移、Gateway 节点故障转移。</li></ul></li><li><p><strong>当前限制与未来计划</strong></p><ul><li><strong>局限性</strong>: Prometheus 多实例数据可能存在间隙，OAuth2 Proxy 不支持机器间认证，部分服务 SSO 集成需手动配置。</li><li><strong>Roadmap</strong>: 扩展 mTLS 覆盖所有服务，审计日志与监控增强，支持自定义根证书。</li></ul></li></ol><h4 id="q-a-重点摘要" tabindex="-1"><strong>Q&amp;A 重点摘要</strong> <a class="header-anchor" href="#q-a-重点摘要" aria-label="Permalink to &quot;**Q&amp;A 重点摘要**&quot;">​</a></h4><ul><li>混合认证模式：不支持同时启用 SSO 和本地用户。</li><li>RGW 集成：理论可行，需测试验证。</li><li>证书管理：未来通过 <code>cephadm</code> 的 Cert Manager 实现自动轮换。</li><li>DNS 支持：当前使用短名称，FQDN 需额外配置。</li><li>网络定制化：VIP 目前绑定公共网络，未来可能支持多网卡选择。</li></ul><h4 id="后续行动计划" tabindex="-1"><strong>后续行动计划</strong> <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;**后续行动计划**&quot;">​</a></h4><ul><li><strong>功能完善</strong>: 补全 Prometheus 数据冗余方案，实现 OAuth2 Proxy 的机器认证支持。</li><li><strong>用户文档</strong>: 编写详细配置指南。</li><li><strong>社区反馈</strong>: 收集企业用户场景需求。</li></ul><h4 id="参会人员反馈" tabindex="-1"><strong>参会人员反馈</strong> <a class="header-anchor" href="#参会人员反馈" aria-label="Permalink to &quot;**参会人员反馈**&quot;">​</a></h4><ul><li>普遍认可新架构的简洁性和安全性提升，关注企业环境落地可行性。</li></ul><p><strong>会议结束时间</strong>: [需补充]<br><strong>资料链接</strong>: [需补充演示文稿或代码库地址]</p><p>（注：部分术语保留英文原词如 <code>cephadm</code>、<code>mTLS</code>、<code>OIDC</code> 以保持技术准确性。）</p>',13)])])}const u=a(n,[["render",i]]);export{h as __pageData,u as default};
